Door scenario''s te ontwikkelen waarin medische kennis onderzoekssuperkracht wordt, autopsiebevindingen cruciale aanwijzingen ontgrendelen, en forensische wetenschap betrouwbaarder blijkt dan getuigenverklaringen, creëren we mysteries die gasten'' verlangen naar verfijnde, bewijs-gebaseerde misdaadoplossing bevredigen.

